# Host-restoring reverse proxy in front of MinIO for SigV4 presigned URLs.
#
# Why this exists:
# MinIO verifies presigned-URL signatures against the request's Host header (SigV4 signs `host`).
# DMS signs upload/download URLs with the public host (S3_PUBLIC_URL, e.g. https://3000-<web_host>).
# An authenticating reverse proxy may rewrite the inbound Host (e.g. to 127.0.0.1:3000) before the
# request reaches oauth2-proxy (the real host is moved to X-Forwarded-Host). oauth2-proxy then passes
# that rewritten Host upstream, so MinIO would see the rewritten value instead of the signed public
# host and reject the request with 403 SignatureDoesNotMatch.
#
# This sidecar sits between oauth2-proxy and MinIO and re-sets Host to the forwarded (signed) host so
# MinIO validates against the host the URL was actually signed with. The request path is preserved
# unchanged (path-style: /dms-local/<key>), so MinIO addressing is identical to talking to it directly.
worker_processes 1;
events { worker_connections 1024; }

http {
    # Prefer the forwarded (signed) host; fall back to the inbound Host header if it is absent.
    map $http_x_forwarded_host $signed_host {
        default $http_x_forwarded_host;
        ''      $http_host;
    }

    server {
        listen 9000;
        server_name _;

        # Object uploads (zips) can be large and must stream through unbuffered.
        client_max_body_size 0;
        proxy_request_buffering off;
        proxy_buffering off;
        proxy_http_version 1.1;

        location / {
            proxy_pass http://minio:9000;
            proxy_set_header Host $signed_host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        }
    }
}
