#!/usr/bin/env python3
"""Minimal OpenAI-compatible LLM endpoint for the SPARK Workflow local stack.

Serves /v1/models, /v1/chat/completions (deterministic stub responses,
honoring response_format=json_object) and /v1/embeddings (deterministic
1024-dim vectors, matching the 1024-dim Qdrant/pgvector columns the app
expects). Accepts any model name. Stdlib only.
"""
import hashlib
import json
import time
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = 8000
EMBED_DIM = 1024


def deterministic_embedding(text: str) -> list[float]:
    h = hashlib.sha512(text.encode("utf-8")).digest()
    vec = []
    counter = 0
    while len(vec) < EMBED_DIM:
        seed = (int.from_bytes(h, "big") + counter * 0x9E3779B97F4A7C15) & (2**256 - 1)
        # 64 floats per 8 sha512 blocks
        block = hashlib.sha512(seed.to_bytes(32, "big")).digest()
        for i in range(0, 64, 8):
            vec.append((int.from_bytes(block[i:i+8], "big") / 2**64) * 2 - 1)
        counter += 1
    norm = sum(v * v for v in vec) ** 0.5 or 1.0
    return [round(v / norm, 8) for v in vec[:EMBED_DIM]]


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    def _send(self, code: int, payload: dict):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path.startswith("/v1/models") or self.path == "/models":
            self._send(200, {
                "object": "list",
                "data": [
                    {"id": "spark-local-text", "object": "model", "owned_by": "local"},
                    {"id": "spark-local-embeddings-1024", "object": "model", "owned_by": "local"},
                    {"id": "spark-local-vision", "object": "model", "owned_by": "local"},
                ],
            })
        elif self.path.startswith("/health") or self.path in ("/", "/v1"):
            self._send(200, {"status": "ok"})
        else:
            self._send(404, {"error": {"message": "not found", "type": "invalid_request_error"}})

    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        try:
            req = json.loads(self.rfile.read(length) or b"{}")
        except json.JSONDecodeError:
            self._send(400, {"error": {"message": "invalid json", "type": "invalid_request_error"}})
            return

        if self.path.startswith("/v1/chat/completions") or self.path.startswith("/v1/completions"):
            model = req.get("model", "spark-local-text")
            rf = req.get("response_format") or {}
            if isinstance(rf, dict) and rf.get("type") == "json_object":
                content = json.dumps({
                    "answer": "local-stub",
                    "summary": "Deterministic stub response from the local LLM endpoint.",
                    "confidence": 0.5,
                })
            else:
                content = "Deterministic stub response from the local LLM endpoint. " \
                          f"(model={model}, prompt_chars={len(json.dumps(req.get('messages', [])))})"
            self._send(200, {
                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                "object": "chat.completion",
                "created": int(time.time()),
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": content},
                    "finish_reason": "stop",
                }],
                "usage": {"prompt_tokens": 10, "completion_tokens": 10, "total_tokens": 20},
            })
        elif self.path.startswith("/v1/embeddings"):
            model = req.get("model", "spark-local-embeddings-1024")
            inputs = req.get("input", "")
            if isinstance(inputs, str):
                inputs = [inputs]
            data = []
            for i, text in enumerate(inputs):
                data.append({
                    "object": "embedding",
                    "index": i,
                    "embedding": deterministic_embedding(str(text)),
                })
            self._send(200, {
                "object": "list",
                "data": data,
                "model": model,
                "usage": {"prompt_tokens": sum(len(str(t)) for t in inputs) // 4,
                          "total_tokens": sum(len(str(t)) for t in inputs) // 4},
            })
        else:
            self._send(404, {"error": {"message": "not found", "type": "invalid_request_error"}})


if __name__ == "__main__":
    print(f"LLM stub listening on http://0.0.0.0:{PORT}/v1", flush=True)
    ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()
